-- Bare-editor fixture for window cwd inspection on Linux, macOS and Windows.
-- No plugin checkouts, interpreters, compilers or GUI are needed.
vim.opt.rtp:prepend(vim.fn.getcwd())
local settings = require("config.settings")
local workspace = require("config.workspace")
local start = vim.fn.getcwd(-1, -1)
local root = vim.fs.normalize(vim.fn.tempname())
local first, second = root .. "/source", root .. "/other"
vim.fn.mkdir(first, "p")
vim.fn.mkdir(second, "p")
local function normalize(path)
  return vim.fs.normalize(path, { expand_env = false })
end
local function directory(path)
  vim.api.nvim_cmd({ cmd = "lcd", args = { path }, magic = { file = false, bar = false } }, {})
end
local source = vim.api.nvim_get_current_win()
directory(first)
vim.cmd.tabnew()
directory(second)
local other = vim.api.nvim_get_current_win()
assert(normalize(vim.api.nvim_win_call(source, function()
  return settings.resolve("cwd")
end)) == first)
assert(normalize(vim.api.nvim_win_call(source, function()
  return settings.resolve("file")
end)) == first)
local data = workspace.snapshot(source)
assert(normalize(data.window_cwd) == first, vim.inspect(data))
assert(normalize(data.debug_root) == first, vim.inspect(data))
assert(normalize(data.launch_file) == first .. "/.vscode/launch.json", vim.inspect(data))
assert(vim.api.nvim_get_current_win() == other)
assert(normalize(vim.fn.getcwd()) == second)
assert(not package.loaded.dap and not package.loaded.scoper and not package.loaded["neo-tree"])
vim.cmd.tabclose()
vim.api.nvim_cmd({ cmd = "cd", args = { start }, magic = { file = false, bar = false } }, {})
vim.fn.delete(root, "rf")
print("Portable source-window context fixture passed")
